using System.Globalization;
using System.Text.Json;
using System.Text.Json.Nodes;

namespace Werkstatt;
/// <summary>Interface language. Each entry lists English, German, Polish, Russian and Simplified Chinese in that order.
/// Counted texts hold their plural forms separated by "|": one|other in English and German, one|few|many in Polish and Russian.</summary>
public static class L
{
    public sealed record Language(string Code,string Name,string Culture){public override string ToString()=>Name;}
    public static readonly Language[] Languages=[new("en","English","en-GB"),new("de","Deutsch","de-DE"),new("pl","Polski","pl-PL"),new("ru","Русский","ru-RU"),new("zh","简体中文","zh-CN")];
    public static Language Current {get;private set;}=Languages[0];
    public static string Code=>Current.Code;
    public static CultureInfo Culture {get;private set;}=CultureInfo.GetCultureInfo("en-GB");
    static int index;
    public static void Use(string code)
    {
        index=Math.Max(0,Array.FindIndex(Languages,l=>l.Code==code));Current=Languages[index];Culture=CultureInfo.GetCultureInfo(Current.Culture);
    }
    /// <summary>Saved choice first, then the Windows display language, then English.</summary>
    public static void Load()
    {
        string? saved=Settings.Text("language");string system=CultureInfo.CurrentUICulture.TwoLetterISOLanguageName;
        Use(saved is {} s&&Languages.Any(l=>l.Code==s)?s:Languages.Any(l=>l.Code==system)?system:"en");
    }
    public static void Save()=>Settings.Store("language",Code);
    public static string T(string key)=>Strings.TryGetValue(key,out var values)?values[index]:key;
    public static string F(string key,params object[] args)=>string.Format(Culture,T(key),args);
    /// <summary>The plural form for <paramref name="count"/>, which is also argument {0}.</summary>
    public static string P(string key,long count,params object[] args)
    {
        var forms=T(key).Split('|');long n=Math.Abs(count)%100,last=n%10;
        int form=forms.Length==1?0:forms.Length==2?count==1?0:1:(Code=="ru"?last==1&&n!=11:count==1)?0:last is >=2 and <=4&&n is <12 or >14?1:2;
        return string.Format(Culture,forms[form],[count,..args]);
    }
    internal static IEnumerable<string> Keys=>Strings.Keys;

