        ["shortcuts.title"]=["Shortcuts","Schnellaktionen","Skróty","Быстрые действия","快捷操作"],
        ["shortcuts.progress"]=["{0} of {1} done","{0} von {1} erledigt","Zrobione: {0} z {1}","Готово: {0} из {1}","已完成 {0}/{1}"],
        ["shortcut.done"]=["Done","Erledigt","Gotowe","Готово","已完成"],
        ["shortcut.nothing"]=["Nothing left to change.","Hier ist nichts mehr zu ändern.","Nie ma już nic do zmiany.","Менять больше нечего.","没有需要更改的内容。"],
        ["shortcut.why.data"]=["This save has no data for it.","Dieser Spielstand enthält dafür keine Daten.","Ten zapis nie zawiera tych danych.","В этом сохранении нет таких данных.","此存档中没有相关数据。"],
        ["shortcut.money"]=["Maximum money","Maximales Geld","Maksimum pieniędzy","Максимум денег","资金拉满"],
        ["shortcut.money.desc"]=["Highest balance the save can store, same as Max next to the money field.","Höchster speicherbarer Kontostand, wie „Max.“ neben dem Geldfeld.","Najwyższe saldo, jakie pomieści zapis – jak „Maks.” przy polu pieniędzy.","Наибольший баланс, который хранит сохранение, как «Макс.» у поля денег.","存档可存储的最高余额，与资金旁的“最大”相同。"],
        ["shortcut.money.done"]=["Money set to the maximum. Review to save.","Geld auf das Maximum gesetzt. Zum Speichern prüfen.","Ustawiono maksimum pieniędzy. Sprawdź, aby zapisać.","Деньги на максимуме. Проверьте и сохраните.","资金已设为最大。检查后保存。"],
        ["shortcut.level"]=["Maximum level","Maximales Level","Maksymalny poziom","Максимальный уровень","等级拉满"],
        ["shortcut.level.desc"]=["XP at the storage limit, which is the top level, same as Max next to Level.","XP am Speicherlimit, also das höchste Level, wie „Max.“ neben dem Level.","XP na limicie zapisu, czyli najwyższy poziom – jak „Maks.” przy poziomie.","Опыт на пределе хранения, то есть высший уровень, как «Макс.» у уровня.","经验值达到存储上限，即最高等级，与等级旁的“最大”相同。"],
        ["shortcut.level.done"]=["Level set to the maximum. Review to save.","Level auf das Maximum gesetzt. Zum Speichern prüfen.","Ustawiono maksymalny poziom. Sprawdź, aby zapisać.","Уровень на максимуме. Проверьте и сохраните.","等级已设为最高。检查后保存。"],
        ["shortcut.skills"]=["All skills and ADR classes","Alle Fähigkeiten und ADR","Wszystkie umiejętności i ADR","Все навыки и классы ADR","全部技能和 ADR 类别"],
        ["shortcut.skills.desc"]=["Every skill at 6 and all six ADR classes, same as Max all.","Jede Fähigkeit auf 6 und alle sechs ADR-Klassen, wie „Alle maximal“.","Każda umiejętność na 6 i wszystkie sześć klas ADR – jak „Wszystko na maks.”.","Все навыки на 6 и все шесть классов ADR, как «Всё на максимум».","所有技能升到 6 级并解锁全部六个 ADR 类别，与“全部拉满”相同。"],
        ["shortcut.skills.done"]=["All skills and ADR classes unlocked. Review to save.","Alle Fähigkeiten und ADR-Klassen freigeschaltet. Zum Speichern prüfen.","Odblokowano wszystkie umiejętności i klasy ADR. Sprawdź, aby zapisać.","Все навыки и классы ADR открыты. Проверьте и сохраните.","已解锁全部技能和 ADR 类别。检查后保存。"],
        ["shortcut.garages.buy"]=["Buy all garages (large)","Alle Garagen kaufen (groß)","Kup wszystkie garaże (duże)","Купить все гаражи (большие)","购买全部车库（大型）"],
        ["shortcut.garages.buy.desc"]=["Buys every garage you don't own as a large one and makes smaller owned ones large.","Kauft jede fehlende Garage als große und baut kleinere eigene groß aus.","Kupuje każdy brakujący garaż jako duży i rozbudowuje mniejsze własne do dużych.","Покупает все недостающие гаражи большими и расширяет свои меньшие до больших.","以大型购买所有未拥有的车库，并把较小的自有车库升为大型。"],
        ["shortcut.garages.upgrade"]=["Make owned garages large","Eigene Garagen groß ausbauen","Powiększ własne garaże","Улучшить свои гаражи","自有车库升为大型"],
        ["shortcut.garages.upgrade.desc"]=["Makes every garage you own large; trucks and drivers keep their slots.","Macht jede eigene Garage groß; Lkw und Fahrer behalten ihre Plätze.","Każdy własny garaż staje się duży; ciężarówki i kierowcy zostają na miejscach.","Все свои гаражи станут большими; грузовики и водители остаются на местах.","将所有自有车库升为大型；卡车和司机保留原车位。"],
        ["shortcut.why.garages"]=["No garages in this save.","Keine Garagen in diesem Spielstand.","Brak garaży w tym zapisie.","В этом сохранении нет гаражей.","此存档中没有车库。"],
        ["shortcut.why.owned"]=["You don't own a garage yet.","Du besitzt noch keine Garage.","Nie masz jeszcze garażu.","У вас ещё нет гаража.","你还没有车库。"],
        ["shortcut.dealers"]=["Unlock truck dealers","Lkw-Händler freischalten","Odblokuj salony ciężarówek","Открыть автосалоны","解锁卡车经销商"],
        ["shortcut.dealers.desc"]=["Lets you buy trucks at the dealer in every city.","Lkw lassen sich beim Händler in jeder Stadt kaufen.","Ciężarówki można kupić w salonie w każdym mieście.","Грузовики можно покупать в автосалоне любого города.","可在每座城市的经销商处购买卡车。"],
        ["shortcut.agencies"]=["Unlock recruitment agencies","Personalagenturen freischalten","Odblokuj agencje rekrutacyjne","Открыть кадровые агентства","解锁招聘机构"],
        ["shortcut.agencies.desc"]=["Lets you hire drivers at the agency in every city.","Fahrer lassen sich bei der Agentur in jeder Stadt anstellen.","Kierowców można zatrudnić w agencji w każdym mieście.","Водителей можно нанимать в агентстве любого города.","可在每座城市的招聘机构雇佣司机。"],
        ["shortcut.repair"]=["Repair all trucks and trailers","Lkw und Anhänger reparieren","Napraw wszystkie pojazdy","Починить всю технику","维修全部卡车和挂车"],
        ["shortcut.repair.desc"]=["Wear to 0 %, permanent wear included; cargo damage cleared.","Verschleiß auf 0 %, auch der dauerhafte; Ladungsschaden beseitigt.","Zużycie do 0 %, także trwałe; uszkodzenia ładunku usunięte.","Износ до 0 %, включая необратимый; повреждения груза устранены.","磨损归零（含永久磨损），并清除货物损坏。"],
        ["shortcut.refuel"]=["Refuel all trucks","Alle Lkw betanken","Zatankuj wszystkie ciężarówki","Заправить все грузовики","为全部卡车加油"],
        ["shortcut.refuel.desc"]=["Fills the tank of every truck you own.","Füllt den Tank jedes eigenen Lkw.","Napełnia bak każdej własnej ciężarówki.","Заполняет бак каждого своего грузовика.","为每辆自有卡车加满油。"],
        ["shortcut.why.trucks"]=["No trucks of your own in this save.","Keine eigenen Lkw in diesem Spielstand.","Brak własnych ciężarówek w tym zapisie.","В этом сохранении нет своих грузовиков.","此存档中没有自己的卡车。"],
        ["shortcut.why.bus"]=["No bus stations in this save.","Keine Busbahnhöfe in diesem Spielstand.","Brak dworców autobusowych w tym zapisie.","В этом сохранении нет автовокзалов.","此存档中没有客运站。"],
        ["shortcut.why.record"]=["No offences on record.","Keine Verstöße im Register.","Brak wykroczeń w kartotece.","Нарушений нет.","没有违规记录。"],
        ["maxout.desc"]=["Top money and level, all skills, large garages, every city and dealer.","Geld, Level, Fähigkeiten, große Garagen, alle Städte und Händler.","Pieniądze, poziom, umiejętności, duże garaże, miasta, salony.","Деньги, уровень, навыки, большие гаражи, все города и салоны.","资金与等级拉满，全部技能，大型车库，所有城市与经销商。"],
        ["maxout.ask"]=["Set top money and top level, unlock every skill and ADR class, make every garage large, mark every city as visited and unlock every truck dealer and recruitment agency?\n\nTrucks and drivers in garages stay where they are. Nothing is written until you review and save.","Höchstes Geld und Level setzen, alle Fähigkeiten und ADR-Klassen freischalten, jede Garage groß machen, jede Stadt als besucht markieren und alle Lkw-Händler und Personalagenturen freischalten?\n\nLkw und Fahrer in Garagen bleiben, wo sie sind. Geschrieben wird erst nach Prüfen und Speichern.","Ustawić maksymalne pieniądze i poziom, odblokować wszystkie umiejętności i klasy ADR, rozbudować każdy garaż do dużego, oznaczyć każde miasto jako odwiedzone i odblokować wszystkie salony ciężarówek i agencje rekrutacyjne?\n\nCiężarówki i kierowcy w garażach zostają na miejscu. Nic nie zostanie zapisane przed sprawdzeniem i zapisem.","Установить максимум денег и уровня, открыть все навыки и классы ADR, сделать все гаражи большими, отметить все города посещёнными и открыть все автосалоны и кадровые агентства?\n\nГрузовики и водители в гаражах остаются на месте. Ничего не записывается до проверки и сохранения.","设置最高资金和等级，解锁所有技能和 ADR 类别，将每座车库设为大型，把每座城市标记为已到访，并解锁所有卡车经销商和招聘机构？\n\n车库中的卡车和司机保持不变。检查并保存之前不会写入任何内容。"],
        ["maxout.done"]=["Account maxed out ({0}, {1}). Review to save.","Konto maximiert ({0}, {1}). Zum Speichern prüfen.","Konto zmaksymalizowane ({0}, {1}). Sprawdź, aby zapisać.","Аккаунт на максимуме ({0}, {1}). Проверьте и сохраните.","账户已拉满（{0}，{1}）。检查后保存。"],
        ["count.garages"]=["{0} garage|{0} garages","{0} Garage|{0} Garagen","{0} garaż|{0} garaże|{0} garaży","{0} гараж|{0} гаража|{0} гаражей","{0} 座车库"],
        ["count.cities"]=["{0} city|{0} cities","{0} Stadt|{0} Städte","{0} miasto|{0} miasta|{0} miast","{0} город|{0} города|{0} городов","{0} 座城市"],
        ["cities.title"]=["Visit all cities","Alle Städte besuchen","Odwiedź wszystkie miasta","Посетить все города","到访所有城市"],
        ["cities.desc"]=["Marks every city as visited, so its jobs appear in the freight market.","Markiert jede Stadt als besucht, damit ihre Aufträge im Frachtmarkt erscheinen.","Oznacza każde miasto jako odwiedzone, by jego zlecenia trafiły na giełdę.","Отмечает все города посещёнными, чтобы их заказы появились на бирже.","将所有城市标记为已到访，其任务会出现在货运市场。"],
        ["cities.done"]=["Visited {0} new city. Review to save.|Visited {0} new cities. Review to save.","{0} neue Stadt besucht. Zum Speichern prüfen.|{0} neue Städte besucht. Zum Speichern prüfen.","Odwiedzono {0} nowe miasto. Sprawdź, aby zapisać.|Odwiedzono {0} nowe miasta. Sprawdź, aby zapisać.|Odwiedzono {0} nowych miast. Sprawdź, aby zapisać.","Посещён {0} новый город. Проверьте и сохраните.|Посещено {0} новых города. Проверьте и сохраните.|Посещено {0} новых городов. Проверьте и сохраните.","新到访 {0} 座城市。检查后保存。"],
        ["drivers.title"]=["Max skills for hired drivers","Angestellte Fahrer maximieren","Maks. umiejętności kierowców","Навыки нанятых водителей","雇佣司机技能拉满"],
        ["drivers.desc"]=["Every hired driver gets all skills and ADR classes.","Jeder angestellte Fahrer bekommt alle Fähigkeiten und ADR-Klassen.","Każdy zatrudniony kierowca dostaje wszystkie umiejętności i klasy ADR.","Каждый нанятый водитель получает все навыки и классы ADR.","每名雇佣司机获得全部技能和 ADR 类别。"],
        ["drivers.none"]=["No hired drivers in this save.","Keine angestellten Fahrer.","Brak zatrudnionych kierowców.","Нет нанятых водителей.","此存档中没有雇佣司机。"],
        ["unlock.done"]=["Unlocked {0}. Review to save.","{0} freigeschaltet. Zum Speichern prüfen.","Odblokowano: {0}. Sprawdź, aby zapisać.","Открыто: {0}. Проверьте и сохраните.","已解锁{0}。检查后保存。"],
        ["count.dealers"]=["{0} truck dealer|{0} truck dealers","{0} Lkw-Händler|{0} Lkw-Händler","{0} salon|{0} salony|{0} salonów","{0} автосалон|{0} автосалона|{0} автосалонов","{0} 家卡车经销商"],
        ["count.agencies"]=["{0} recruitment agency|{0} recruitment agencies","{0} Personalagentur|{0} Personalagenturen","{0} agencja|{0} agencje|{0} agencji","{0} кадровое агентство|{0} кадровых агентства|{0} кадровых агентств","{0} 家招聘机构"],
        ["busstops.title"]=["Discover bus stations (beta)","Busbahnhöfe entdecken (Beta)","Dworce autobusowe (beta)","Открыть автовокзалы (бета)","发现所有客运站（实验）"],
        ["busstops.desc"]=["Experimental: marks every bus station as discovered. Not yet confirmed in the game.","Experimentell: Jeder Busbahnhof gilt als entdeckt. Im Spiel noch nicht bestätigt.","Eksperymentalne: oznacza każdy dworzec jako odkryty. Jeszcze niepotwierdzone w grze.","Экспериментально: все автовокзалы станут открытыми. В игре пока не проверено.","实验性功能：将所有客运站标记为已发现。尚未在游戏中确认。"],
        ["busstops.done"]=["Discovered {0} bus station. Review to save.|Discovered {0} bus stations. Review to save.","{0} Busbahnhof entdeckt. Zum Speichern prüfen.|{0} Busbahnhöfe entdeckt. Zum Speichern prüfen.","Odkryto {0} dworzec. Sprawdź, aby zapisać.|Odkryto {0} dworce. Sprawdź, aby zapisać.|Odkryto {0} dworców. Sprawdź, aby zapisać.","Открыт {0} автовокзал. Проверьте и сохраните.|Открыто {0} автовокзала. Проверьте и сохраните.|Открыто {0} автовокзалов. Проверьте и сохраните.","已发现 {0} 个客运站。检查后保存。"],
        ["record.title"]=["Clean record","Strafregister löschen","Wyczyść kartotekę","Очистить нарушения","清除违规记录"],
        ["record.desc"]=["Resets offence and fine statistics.","Verstöße und Bußgelder auf null.","Zeruje wykroczenia i mandaty.","Обнуляет нарушения и штрафы.","违规和罚款统计清零。"],
        ["record.done"]=["Offence record cleared. Review to save.","Strafregister gelöscht. Zum Speichern prüfen.","Kartoteka wyczyszczona. Sprawdź, aby zapisać.","Нарушения обнулены. Проверьте и сохраните.","违规记录已清除。检查后保存。"],
        ["count.offences"]=["{0} offence|{0} offences","{0} Verstoß|{0} Verstöße","{0} wykroczenie|{0} wykroczenia|{0} wykroczeń","{0} нарушение|{0} нарушения|{0} нарушений","{0} 次违规"],
