        ["status.busy"]=["Please wait until the current task has finished.","Bitte warten, bis der aktuelle Vorgang abgeschlossen ist.","Poczekaj na zakończenie bieżącej operacji.","Дождитесь завершения текущей операции.","请等待当前任务完成。"],
        ["status.opening"]=["Decrypting and checking save…","Spielstand wird entschlüsselt und geprüft …","Odszyfrowywanie i sprawdzanie zapisu…","Расшифровка и проверка сохранения…","正在解密并检查存档…"],
        ["status.nochanges"]=["No changes staged.","Keine Änderungen vorgemerkt.","Brak przygotowanych zmian.","Нет подготовленных изменений.","没有暂存的更改。"],
        ["status.wait"]=["A file operation is still being verified. Please wait a moment.","Dateivorgang wird noch geprüft. Bitte kurz warten.","Operacja na pliku jest jeszcze sprawdzana. Chwileczkę.","Файловая операция ещё проверяется. Подождите немного.","文件操作仍在验证中，请稍候。"],
        ["status.writing"]=["Backing up, writing and fully re-checking the file…","Datei wird gesichert, geschrieben und vollständig nachgeprüft …","Tworzenie kopii, zapis i pełna weryfikacja pliku…","Резервное копирование, запись и полная проверка файла…","正在备份、写入并完整复查文件…"],
        ["dialog.unsaved"]=["Unsaved changes","Ungespeicherte Änderungen","Niezapisane zmiany","Несохранённые изменения","未保存的更改"],
        ["dialog.discard.open"]=["Discard the staged changes and open the other file?","Vorgemerkte Änderungen verwerfen und die andere Datei öffnen?","Odrzucić przygotowane zmiany i otworzyć inny plik?","Сбросить подготовленные изменения и открыть другой файл?","放弃暂存的更改并打开另一个文件？"],
        ["dialog.discard.close"]=["Close without saving and discard the staged changes?","Ohne Speichern schließen und vorgemerkte Änderungen verwerfen?","Zamknąć bez zapisu i odrzucić przygotowane zmiany?","Закрыть без сохранения и сбросить подготовленные изменения?","不保存就关闭并放弃暂存的更改？"],
        ["dialog.discard"]=["Discard","Verwerfen","Odrzuć","Сбросить","放弃"],
        ["dialog.open.title"]=["Open ETS2 save","ETS2-Spielstand öffnen","Otwórz zapis ETS2","Открыть сохранение ETS2","打开 ETS2 存档"],
        ["dialog.open.filter"]=["SCS save games","SCS-Spielstände","Zapisy SCS","Сохранения SCS","SCS 存档"],
        ["dialog.open.all"]=["All files","Alle Dateien","Wszystkie pliki","Все файлы","所有文件"],
        ["reset.title"]=["Discard changes","Änderungen verwerfen","Odrzuć zmiany","Сбросить изменения","放弃更改"],
        ["reset.ask"]=["Discard all staged changes? The file on disk stays as it is.","Alle vorgemerkten Änderungen verwerfen? Die Datei auf der Festplatte bleibt unverändert.","Odrzucić wszystkie przygotowane zmiany? Plik na dysku pozostanie bez zmian.","Сбросить все подготовленные изменения? Файл на диске останется без изменений.","放弃所有暂存的更改？磁盘上的文件保持不变。"],
        ["input.range"]=["{0}: enter a whole number from {1} to {2}.","{0}: ganze Zahl zwischen {1} und {2} eingeben.","{0}: wpisz liczbę całkowitą od {1} do {2}.","{0}: введите целое число от {1} до {2}.","{0}：请输入 {1} 到 {2} 之间的整数。"],
        ["num.invalid"]=["Enter a number, e.g. {0}, {1} or 1,000,000.","Zahl eingeben, z. B. {0}, {1} oder 1.000.000.","Wpisz liczbę, np. {0}, {1} lub 1 000 000.","Введите число, например {0}, {1} или 1 000 000.","请输入数字，例如 {0}、{1} 或 1,000,000。"],
        ["num.units"]=["Units: {0}","Einheiten: {0}","Jednostki: {0}","Единицы: {0}","单位：{0}"],
        ["num.separators"]=["Check the thousands and decimal separators.","Tausender- und Dezimaltrennzeichen prüfen.","Sprawdź separatory tysięcy i miejsc dziesiętnych.","Проверьте разделители тысяч и десятичных.","请检查千位和小数分隔符。"],
        ["num.bad"]=["Invalid number.","Ungültige Zahl.","Nieprawidłowa liczba.","Недопустимое число.","数字无效。"],
        ["num.overflow"]=["The number exceeds the save limit.","Die Zahl überschreitet das Save-Limit.","Liczba przekracza limit zapisu.","Число превышает предел сохранения.","数字超出存档上限。"],
        ["num.range"]=["Allowed: 0 to {0}.","Erlaubt: 0 bis {0}.","Dozwolone: od 0 do {0}.","Допустимо: от 0 до {0}.","允许范围：0 到 {0}。"],
        ["num.range.signed"]=["Allowed: {0} to {1}.","Erlaubt: {0} bis {1}.","Dozwolone: od {0} do {1}.","Допустимо: от {0} до {1}.","允许范围：{0} 到 {1}。"],
        ["money.negative"]=["A minus sign sets a debt, e.g. {0}.","Mit Minus setzt du Schulden, z. B. {0}.","Minus ustawia dług, np. {0}.","Минус задаёт долг, например {0}.","输入负号即为负债，例如 {0}。"],
        ["num.whole"]=["The stored value must be a whole number.","Der gespeicherte Wert muss eine ganze Zahl sein.","Zapisana wartość musi być liczbą całkowitą.","Сохраняемое значение должно быть целым.","存储的数值必须是整数。"],
        ["money.title"]=["Money","Geld","Pieniądze","Деньги","资金"],
        ["money.max.tip"]=["Technical save limit: {0} €. Further income can overflow the value.","Technisches Save-Limit: {0} €. Weitere Einnahmen können den Wert überlaufen lassen.","Techniczny limit zapisu: {0} €. Kolejne przychody mogą przepełnić wartość.","Технический предел: {0} €. Дальнейший доход может вызвать переполнение.","技术存档上限：{0} €。继续获得收入可能导致数值溢出。"],
        ["money.limit"]=["Save limit reached. More income can overflow.","Save-Limit erreicht; Einnahmen können überlaufen.","Osiągnięto limit zapisu. Przychód może go przepełnić.","Лимит сохранения. Доход может его переполнить.","已达到存档上限。继续获得收入可能导致溢出。"],
        ["money.units"]=["Short forms: {0}","Kurzformen: {0}","Skróty: {0}","Сокращения: {0}","简写：{0}"],
        ["xp.title"]=["Experience","Erfahrung","Doświadczenie","Опыт","经验"],
        ["xp.level"]=["Level","Level","Poziom","Уровень","等级"],
        ["xp.max.tip"]=["Technical XP limit: {0}. More XP can overflow the value.","Technisches XP-Limit: {0}. Weitere XP können den Wert überlaufen lassen.","Techniczny limit XP: {0}. Kolejne XP mogą przepełnić wartość.","Технический предел опыта: {0}. Дальнейший опыт может вызвать переполнение.","技术经验上限：{0}。继续获得经验可能导致数值溢出。"],
        ["xp.limit"]=["XP limit reached. More XP may cause an overflow.","XP-Limit erreicht. Mehr XP können überlaufen.","Osiągnięto limit XP. Kolejne XP mogą go przepełnić.","Лимит опыта. Новый опыт может его переполнить.","已达到经验上限。继续获得经验可能导致溢出。"],
        ["xp.hint"]=["Levels follow the ETS2 curve. Economy mods may differ.","Level nach ETS2-Kurve. Economy-Mods können abweichen.","Poziomy według krzywej ETS2. Mody ekonomii mogą się różnić.","Уровни по кривой ETS2. Экономические моды могут отличаться.","等级按 ETS2 曲线计算，经济类模组可能不同。"],
        ["xp.curve"]=["XP curve: {0}","XP-Kurve: {0}","Krzywa XP: {0}","Кривая опыта: {0}","经验曲线：{0}"],
