        ["xp.next"]=["Level {0} · {1} XP to level {2}","Level {0} · noch {1} XP bis Level {2}","Poziom {0} · {1} XP do poziomu {2}","Уровень {0} · ещё {1} XP до уровня {2}","等级 {0} · 距离等级 {2} 还差 {1} XP"],
        ["xp.range"]=["Level must be between 0 and {0}.","Level muss zwischen 0 und {0} liegen.","Poziom musi mieścić się między 0 a {0}.","Уровень должен быть от 0 до {0}.","等级必须在 0 到 {0} 之间。"],
