        ["status.maxout.none"]=["Everything is already at its maximum.","Alles ist bereits am Maximum.","Wszystko jest już na maksimum.","Всё уже на максимуме.","一切已是最大值。"],
        ["vehicle.truck"]=["Truck","Lkw","Ciężarówka","Грузовик","卡车"],
