/// <summary>settings.json, read-modify-write so the language and the guide flag never overwrite each other.</summary>
internal static class Settings
{
    static string Location=>Path.Combine(SaveSession.DataRoot,"settings.json");
    static JsonObject Read()
    {
        try{if(File.Exists(Location)&&JsonNode.Parse(File.ReadAllText(Location)) is JsonObject settings)return settings;}
        catch(Exception e) when(e is IOException or UnauthorizedAccessException or JsonException){}
        return new JsonObject();
    }
    public static string? Text(string key)=>Read()[key] is JsonValue value&&value.TryGetValue(out string? text)?text:null;
    public static int Number(string key)=>Read()[key] is JsonValue value&&value.TryGetValue(out int number)?number:0;
    public static void Store(string key,JsonNode value)
    {
        try{var settings=Read();settings[key]=value;Directory.CreateDirectory(SaveSession.DataRoot);File.WriteAllText(Location,settings.ToJsonString());}
        catch(Exception e) when(e is IOException or UnauthorizedAccessException){}
    }
}
